import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';
import '../crm_providers.dart';
import '../data/crm_inbox_repository.dart';

class CrmScreen extends ConsumerWidget { const CrmScreen({super.key}); @override Widget build(BuildContext c, WidgetRef r) => Scaffold(appBar: AppBar(title: const Text('CRM')), body: r.watch(crmContactsProvider).when(loading: () => const Center(child: CircularProgressIndicator()), error: (e, _) => Center(child: Text('$e')), data: (items) => ListView(children: items.map((item) => ListTile(title: Text(item.name), subtitle: Text([item.phone, item.email].where((value) => value.isNotEmpty).join(' • ')), onTap: () => c.go('/crm/contacts/${item.id}'))).toList()))); }
class ContactDetailScreen extends ConsumerWidget { const ContactDetailScreen({super.key, required this.id}); final String id; @override Widget build(BuildContext c, WidgetRef r) => Scaffold(appBar: AppBar(title: const Text('Contact')), body: FutureBuilder<CrmContact>(future: r.read(crmInboxRepositoryProvider).contact(id), builder: (c, snapshot) { if (!snapshot.hasData) return const Center(child: CircularProgressIndicator()); final contact = snapshot.data!; return ListView(padding: const EdgeInsets.all(16), children: [Text(contact.name, style: Theme.of(c).textTheme.headlineSmall), Text(contact.phone), Text(contact.email), Text(contact.company)]); })); }
class InboxScreen extends ConsumerWidget { const InboxScreen({super.key}); @override Widget build(BuildContext c, WidgetRef r) => Scaffold(appBar: AppBar(title: const Text('Unified Inbox')), body: r.watch(inboxConversationsProvider).when(loading: () => const Center(child: CircularProgressIndicator()), error: (e, _) => Center(child: Text('$e')), data: (items) => ListView(children: items.map((item) => ListTile(title: Text(item.channel.toUpperCase()), subtitle: Text(item.lastActivity), onTap: () => c.go('/inbox/${item.id}'))).toList()))); }
class ConversationScreen extends ConsumerWidget { const ConversationScreen({super.key, required this.id}); final String id; @override Widget build(BuildContext c, WidgetRef r) { final repo = r.read(crmInboxRepositoryProvider); return Scaffold(appBar: AppBar(title: const Text('Conversation')), body: FutureBuilder<List<UnifiedMessage>>(future: repo.messages(id), builder: (c, snapshot) => snapshot.hasData ? ListView(children: snapshot.data!.map((message) => ListTile(title: Text(message.content), subtitle: Text(message.direction))).toList()) : const Center(child: CircularProgressIndicator()))); } }
